export type CaseLocale = "en" | "ru";
export type CaseStudyType = "case" | "industry-scenario";

export type CaseContentBlock = {
  intro: string;
  bullets?: string[];
};

export type CasePageContent = {
  cardTitle: string;
  title: string;
  category: string;
  label: string;
  short: string;
  heroTitle: string;
  intro: string;
  about: string;
  startingPoint: CaseContentBlock;
  projectGoal: CaseContentBlock;
  automationStrategy: CaseContentBlock;
  workflowArchitecture: string[];
  implemented: string[];
  toolsStack: string[];
  businessEconomics: CaseContentBlock;
  expectedResults: string[];
  whatBusinessGets: string[];
  conclusion: string;
  ctaLabel: string;
  ctaHref: string;
  ctaBody: string;
};

export type CaseStudy = {
  slug: string;
  type?: CaseStudyType;
  title: string;
  category: string;
  label: string;
  short: string;
  problem: string[];
  startingPoint: string;
  solution: string;
  workflow: string[];
  tools: string[];
  expectedOutcome: string[];
  imagePath: string;
  imageAlt: string;
  localized?: Partial<Record<CaseLocale, CasePageContent>>;
};

export function getCaseCardCopy(caseStudy: CaseStudy, locale: CaseLocale) {
  const localized = caseStudy.localized?.[locale];

  return {
    title: localized?.cardTitle ?? caseStudy.title,
    category: localized?.category ?? caseStudy.category,
    label: localized?.label ?? caseStudy.label,
    short: localized?.short ?? caseStudy.short,
  };
}

export function getCasePageContent(caseStudy: CaseStudy, locale: CaseLocale) {
  return caseStudy.localized?.[locale] ?? null;
}

